package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_2 : Integer;
    attribute accumulatedMs : Integer := 0;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_2;
      then if accumulatedMs >= 1000 {
        first start;
        then assign accumulatedMs := accumulatedMs - 1000;
      }
    }
    out attribute serial_0_trigger : Boolean = accumulatedMs >= 1000;
    out attribute serial_0_value_0 : Real = io_0;
    out attribute serial_0_value_1 : Boolean = io_1;
  }
  part system : Controller;
}
